SELECT r.id,r.content_generation,r.source_revision,COALESCE((SELECT IF(s.id IS NULL,'',SHA2(CAST(JSON_ARRAY('song_artifact',r.id,s.song_source_ref_id,r.artifact_type,r.source_checksum,r.processor_version,r.schema_version) AS CHAR),256)) FROM song_resources s WHERE r.source_resource_id=s.id),''),r.status,r.claim_generation,COALESCE(r.running_batch_id,''),r.reference_sha256,r.reference_size_bytes,r.local_content_generation,r.local_target_revision,r.local_skip_generation,r.local_skip_target_revision,r.local_skip_baseline,r.local_skip_reason,COALESCE(r.local_path,''),COALESCE(r.checksum,''),r.size_bytes
FROM song_resource_artifacts r WHERE r.id=? FOR UPDATE
